// pulls the font awesome free glyphs blackwaves actually uses into one small
// generated file, so the app ships ~80 icons instead of all 2,000.
// usage: node scripts/build-icons.js   (needs the @fortawesome dev dependencies)
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const solid = require("@fortawesome/free-solid-svg-icons");
const regular = require("@fortawesome/free-regular-svg-icons");
const brands = require("@fortawesome/free-brands-svg-icons");
const version = require("@fortawesome/free-solid-svg-icons/package.json").version;

// our name: [font awesome name, style]. "toggle" means the regular (outline)
// glyph normally and the solid one when the icon is switched on.
const MAP = {
  home: ["house", "solid"],
  browser: ["globe", "solid"],
  games: ["gamepad", "solid"],
  movies: ["clapperboard", "solid"],
  music: ["music", "solid"],
  manga: ["book-open", "solid"],
  cloud: ["cloud", "solid"],
  chat: ["comments", "solid"],
  shop: ["bag-shopping", "solid"],
  bell: ["bell", "toggle"],
  settings: ["gear", "solid"],
  user: ["user", "solid"],
  users: ["user-group", "solid"],
  search: ["magnifying-glass", "solid"],
  plus: ["plus", "solid"],
  x: ["xmark", "solid"],
  back: ["arrow-left", "solid"],
  forward: ["arrow-right", "solid"],
  refresh: ["rotate-right", "solid"],
  star: ["star", "toggle"],
  heart: ["heart", "toggle"],
  play: ["play", "solid"],
  pause: ["pause", "solid"],
  next: ["forward-step", "solid"],
  prev: ["backward-step", "solid"],
  volume: ["volume-high", "solid"],
  mute: ["volume-xmark", "solid"],
  fullscreen: ["expand", "solid"],
  external: ["arrow-up-right-from-square", "solid"],
  menu: ["bars", "solid"],
  dots: ["ellipsis-vertical", "solid"],
  coin: ["coins", "solid"],
  send: ["paper-plane", "solid"],
  smile: ["face-smile", "regular"],
  trash: ["trash-can", "solid"],
  edit: ["pen", "solid"],
  reply: ["reply", "solid"],
  hash: ["hashtag", "solid"],
  at: ["at", "solid"],
  lock: ["lock", "solid"],
  shield: ["shield-halved", "solid"],
  palette: ["palette", "solid"],
  sparkles: ["wand-magic-sparkles", "solid"],
  info: ["circle-info", "solid"],
  discord: ["discord", "brands"],
  github: ["github", "brands"],
  check: ["check", "solid"],
  down: ["chevron-down", "solid"],
  right: ["chevron-right", "solid"],
  eyeOff: ["eye-slash", "solid"],
  clock: ["clock", "regular"],
  pin: ["location-dot", "solid"],
  logout: ["right-from-bracket", "solid"],
  shuffle: ["shuffle", "solid"],
  repeat: ["repeat", "solid"],
  tv: ["tv", "solid"],
  image: ["image", "regular"],
  grid: ["table-cells-large", "solid"],
  list: ["list", "solid"],
  gift: ["gift", "solid"],
  crown: ["crown", "solid"],
  zap: ["bolt", "solid"],
  copy: ["copy", "regular"],
  download: ["download", "solid"],
  upload: ["upload", "solid"],
  wave: ["water", "solid"],
  ban: ["ban", "solid"],
  flag: ["flag", "toggle"],
  bookmark: ["bookmark", "toggle"],
  maximize: ["up-right-and-down-left-from-center", "solid"],
  minimize: ["down-left-and-up-right-to-center", "solid"],
  ai: ["robot", "solid"],
  stop: ["stop", "solid"],
  newChat: ["pen-to-square", "regular"],
  retry: ["rotate-left", "solid"],
};

const camel = (name) => "fa" + name.replace(/(^|-)([a-z0-9])/g, (_, __, c) => c.toUpperCase());
function glyph(pack, name) {
  const def = pack[camel(name)];
  if (!def) throw new Error(`font awesome has no ${name} in that style`);
  const [width, height, , , d] = def.icon;
  return [width, height, Array.isArray(d) ? d.join(" ") : d];
}

const out = {};
for (const [ours, [name, style]] of Object.entries(MAP)) {
  if (style === "toggle") out[ours] = [...glyph(regular, name), glyph(solid, name)[2]];
  else out[ours] = glyph(style === "brands" ? brands : style === "regular" ? regular : solid, name);
}

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const lines = Object.entries(out).map(([name, value]) => `  ${name}: ${JSON.stringify(value)},`);
const file = `// generated by scripts/build-icons.js, edit the map there instead.
// Font Awesome Free ${version} by @fontawesome - https://fontawesome.com
// License - https://fontawesome.com/license/free (Icons: CC BY 4.0)
// [width, height, path, solid path for toggled-on icons]
export const GLYPHS = {
${lines.join("\n")}
};
`;
fs.writeFileSync(path.join(root, "src/components/glyphs.js"), file);
console.log(`wrote ${Object.keys(out).length} icons, ${(file.length / 1024).toFixed(1)} KB`);
